-- Zonas: de un puñado de municipios de la bahía de Santander a un buscador
-- de lugares de toda España (19 comunidades autónomas + 8132 municipios,
-- dataset del INE vía https://github.com/codeforspain/ds-organizacion-administrativa).
--
-- Cada zona es 'comunidad' (p.ej. Cantabria entera) o 'municipio' (p.ej. Santander),
-- con comunidad_slug enlazando cada municipio a su comunidad para poder cruzar
-- "trabajo en toda Cantabria" con una búsqueda por "Santander" y viceversa.

alter table zonas add column tipo text not null default 'municipio' check (tipo in ('comunidad', 'municipio'));
alter table zonas add column comunidad_slug text;
alter table zonas add column ine_id text;
alter table zonas alter column tipo drop default;

create index zonas_comunidad_slug_idx on zonas (comunidad_slug);

-- Las 6 zonas creadas a mano en la Fase 2 pasan a ser municipios de Cantabria
-- (se actualizan in situ para no romper profesional_zonas / solicitudes.zona_id).
update zonas set tipo = 'municipio', comunidad_slug = 'cantabria', ine_id = '39075' where id = 'a978dd45-419b-4062-b135-813ff24a4dc0';
